const base = `.x-demo{box-sizing:border-box;width:min(335px,90vw);padding:22px;color:#e0e0e0;font-family:system-ui}.x-eyebrow{display:block;font:8px monospace;letter-spacing:1.5px;color:#707070}.x-title{font:500 21px/1.2 system-ui;letter-spacing:-.7px;margin:12px 0}.x-note{font:10px/1.5 system-ui;color:#777777;margin:9px 0 0}.x-panel{border:1px solid #303030;background:#161616;border-radius:12px;padding:20px}.x-demo button{font-family:inherit;cursor:pointer}.x-demo button:focus-visible,.x-demo input:focus-visible{outline:2px solid var(--accent,#ececec);outline-offset:3px}.x-accent{color:var(--accent,#ececec)}.x-demo [hidden]{display:none!important}.x-demo button:disabled{opacity:.35;cursor:default}`;
const make=(id,name,category,description,tags,html,css,js='',isNew=false)=>({id,name,category,description,tags,isNew,html,css:base+css,js});
const svg=p=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`;
